{"results": [{"id": "hp_doc_cce5a053a012c4d72e006b0646cb1be8dc0d88d0e4e28829bdc4b9229826f0b0", "title": "Electoral district of Ivanhoe", "text": "The Electoral district of Ivanhoe is an electoral district of the Victorian Legislative Assembly. It is located in the north-eastern suburbs of Melbourne and includes the suburbs of Heidelberg, Ivanhoe, Rosanna and Macleod.", "score": 29.8541}, {"id": "hp_doc_d78653129be55bb6fe8321f03545d9c2f6dd4816b9c80f0882b05de9447bc289", "title": "Electoral results for the district of Ivanhoe", "text": "This is a list of electoral results for the Electoral district of Ivanhoe in Victorian state elections.", "score": 29.6041}, {"id": "hp_doc_382e0f6a27eec37af32f0efa78aef214fbcaeddf0186211f844b6a1d812be662", "title": "Electoral district of Ivanhoe (Western Australia)", "text": "The Electoral district of Ivanhoe was a Legislative Assembly electorate in the state of Western Australia. It was named for a local settlement, and covered part of the Goldfields city of Boulder, near Kalgoorlie. It was created at the 1904 redistribution and was merged in 1911 with the neighbouring seat of Brown Hill to form the Electoral district of Brown Hill-Ivanhoe. The only Member for Ivanhoe was John Scaddan of the Australian Labor Party.", "score": 27.2108}], "remaining_searches": 2}
