{"results": [{"id": "hp_doc_cce5a053a012c4d72e006b0646cb1be8dc0d88d0e4e28829bdc4b9229826f0b0", "title": "Electoral district of Ivanhoe", "text": "The Electoral district of Ivanhoe is an electoral district of the Victorian Legislative Assembly. It is located in the north-eastern suburbs of Melbourne and includes the suburbs of Heidelberg, Ivanhoe, Rosanna and Macleod.", "score": 29.3353}, {"id": "hp_doc_d1dac4c353a07010b32b844937904499bef5e52e8acf888a892aa2be014088d9", "title": "Ivanhoe, Victoria", "text": "Ivanhoe is a suburb of Melbourne, Victoria, Australia, 10 km north-east of Melbourne's Central Business District. Its local government area is the City of Banyule. At the 2016 Census, Ivanhoe had a population of 12,171.", "score": 18.5855}, {"id": "hp_doc_bfcc328c20e2fe2ed91040888ed30f630bc12aa37ebf29d3fc5f2a913f0242c3", "title": "Western Highway (Victoria)", "text": "The Western Highway is the Victorian part of the principal route linking the Australian cities of Melbourne and Adelaide with a length of approximately 314 km of single carriageway then 156 km of dual carriageway known as the Western Freeway. It is a part of the National Highway network and designated as National Highway A8 and M8. The western end continues in South Australia as the Dukes Highway, the next section of the Melbourne–Adelaide National Highway. The Western Freeway joins Melbourne's freeway network via the Western Ring Road, in the middle western suburbs of Melbourne.", "score": 14.1534}], "remaining_searches": 1}
